      if (this.totalBudget > 0) {
        return `Accumulated cost: ${this.formatCoins(this.totalCost)} of ${this.formatCoins(this.totalBudget)} cxj (${label})`
      }
      return `Accumulated cost: ${this.formatCoins(this.totalCost)} cxj (${label})`
    }
  },
